(function(){
  var _cs = document.currentScript;
  function el(tag, attrs, txt){
    var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");

  var data=[{d:"12 août",v:82.17},{d:"13 août",v:80.44},{d:"14 août",v:82.40},{d:"17 août",v:84.50},{d:"18 août",v:84.06},{d:"19 août",v:84.39},{d:"20 août",v:86.83},{d:"21 août",v:87.06},{d:"24 août",v:85.01},{d:"25 août",v:82.36},{d:"26 août",v:82.23},{d:"27 août",v:83.53},{d:"28 août",v:83.40},{d:"31 août",v:85.76},{d:"1er sept.",v:90.22},{d:"2 sept.",v:91.01},{d:"3 sept.",v:91.30},{d:"4 sept.",v:91.48},{d:"6 sept.",v:92.09},{d:"7 sept.",v:92.52},{d:"8 sept.",v:93.03},{d:"9 sept.",v:96.05},{d:"10 sept.",v:102.48},{d:"11 sept.",v:100.05}];
  var events=[{i:15,label:"BdC maintient à 2,25\u00a0%"},{i:21,label:"Frappe houthie sur Aramco"}];

  var margin={left:62,right:24,top:18,bottom:46};
  var PW=680-margin.left-margin.right, PH=300-margin.top-margin.bottom;
  var n=data.length;
  var vMin=Math.min.apply(null,data.map(function(p){return p.v;}));
  var vMax=Math.max.apply(null,data.map(function(p){return p.v;}));
  var pad=(vMax-vMin)*0.12;
  var yMin=vMin-pad, yMax=vMax+pad;
  var xp=function(i){ return margin.left + (i/(n-1))*PW; };
  var yp=function(v){ return margin.top + PH - ((v-yMin)/(yMax-yMin))*PH; };

  var gridN=4;
  for(var g=0; g<=gridN; g++){
    var gy = margin.top + (g/gridN)*PH;
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":0.5}));
  }

  var dpath = data.map(function(p,i){ return (i===0?"M":"L")+xp(i).toFixed(1)+","+yp(p.v).toFixed(1); }).join(" ");
  svg.appendChild(el("path",{d:dpath,fill:"none",stroke:"#4a5568","stroke-width":1.6}));

  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":1}));
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":1}));

  for(var gy2=0; gy2<=gridN; gy2++){
    var val = yMax - (gy2/gridN)*(yMax-yMin);
    var yy = margin.top + (gy2/gridN)*PH;
    svg.appendChild(el("text",{x:margin.left-6,y:yy+3,"text-anchor":"end","font-size":8.5,fill:"#aaaaaa"}, val.toFixed(0)+"\u00a0$"));
  }

  for(var i=0;i<n;i++){
    if(i%4===0 || i===n-1){
      svg.appendChild(el("text",{x:xp(i),y:margin.top+PH+16,"text-anchor":"middle","font-size":8,fill:"#999999"}, data[i].d));
    }
  }

  events.forEach(function(ev){
    var ex=xp(ev.i);
    var nearRight=(ex+70+3)>(margin.left+PW);
    var anchor= nearRight ? "end" : "start";
    var offset= nearRight ? -6 : 6;
    svg.appendChild(el("line",{x1:ex,x2:ex,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":0.5,"stroke-dasharray":"2,3"}));
    var words=ev.label.split(" ");
    var lines=[];
    words.forEach(function(w){
      var last=lines[lines.length-1];
      if(last && (last+" "+w).length<=16){ lines[lines.length-1]=last+" "+w; } else { lines.push(w); }
    });
    lines.forEach(function(ln,li){
      svg.appendChild(el("text",{x:ex+offset,y:margin.top+16+li*10,"text-anchor":anchor,"font-size":7,"font-weight":700,fill:"#1a3560"}, ln));
    });
  });

  var lastX=xp(n-1), lastY=yp(data[n-1].v);
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));

  var pillText=data[n-1].v.toFixed(2).replace(".", ",")+"\u00a0$";
  var pillW=Math.ceil(pillText.length*9*0.58)+10;
  var pillH=16;
  var pillX=lastX-pillW-6;
  if(pillX<margin.left) pillX=margin.left;
  var pillY=lastY-pillH/2;
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:3,fill:"#e8a825"}));
  svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":9,"font-weight":700,fill:"#111111"}, pillText));

  _cs.parentNode.appendChild(svg);
})();
</script>
